{
  "name": "@r3nic1e/opencode-pr-tracker",
  "version": "0.2.0",
  "description": "Tracks pull requests created through the GitHub MCP in each session and shows their status in the sidebar.",
  "type": "module",
  "license": "MIT",
  "author": "Sviatoslav Dumchenko",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/r3nic1e/opencode-plugins.git",
    "directory": "packages/pr-tracker"
  },
  "homepage": "https://github.com/r3nic1e/opencode-plugins/tree/main/packages/pr-tracker#readme",
  "bugs": {
    "url": "https://github.com/r3nic1e/opencode-plugins/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./dist/tui.js",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src",
    "dist",
    "README.md"
  ],
  "scripts": {
    "prepack": "node ../../scripts/build-tui.mjs ."
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  }
}
